#!/usr/bin/env node
/**
 * Tests for scripts/gate.mjs: the test command under a stuck check, the wait cap, the scope check, the
 * unchanged-tree skip, the format-only list and the red proof. Each case runs in its own temp git repository;
 * the commands are tiny `node -e` programs, and the minutes are fractions so every case takes seconds.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'gate.mjs');
const OK = 'node -e "process.exit(0)"';
const FAIL = 'node -e "process.exit(1)"';
const STAMP = 'node -e "console.log(Date.now())"'; // a run leaves a fresh stamp in the log, a skip leaves it alone
const STUCK = 'node -e "console.log(\'start\');setInterval(()=>{},1000)"';
const SLOW = 'node -e "console.log(\'start\');let n=0;const t=setInterval(()=>{console.log(\'tick\');if(++n>=25)clearInterval(t)},100)"';
const created = [];

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

const git = (root, ...args) => spawnSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...args], { cwd: root, encoding: 'utf8' }).stdout.trim();

/** A temp git repository with one commit and an active perimeter of `entries` (none: no perimeter file): `{ root, head }`. */
function repo(entries = ['**']) {
  const root = mkdtempSync(join(tmpdir(), 'gate-'));
  created.push(root);
  git(root, 'init');
  writeFileSync(join(root, 'README.md'), 'hello\n');
  git(root, 'add', '-A');
  git(root, 'commit', '-m', 'init');
  if (entries) {
    const dir = join(root, '.git', 'deliver');
    mkdirSync(dir, { recursive: true });
    const branch = git(root, 'rev-parse', '--abbrev-ref', 'HEAD');
    writeFileSync(join(dir, 'perimeter.md'), `branch: ${branch}\nstatus: active\n${entries.map((e) => `- ${e}`).join('\n')}\n`);
  }
  return { root, head: git(root, 'rev-parse', 'HEAD') };
}

const logOf = (r) => readFileSync(join(r.root, '.git', 'deliver', 'gate.log'), 'utf8');

// NODE_TEST_CONTEXT would make the `node --test` the gate runs report into this run instead of printing its own
const { NODE_TEST_CONTEXT, ...env } = process.env;
const gate = (root, ...args) => spawnSync(process.execPath, [SCRIPT, '--root', root, ...args], { encoding: 'utf8', env });
const run = (r, command, ...args) => gate(r.root, '--head', r.head, '--test', command, ...args);
const KEYS = ['gate', 'test', 'outside', 'formatOnly', 'tree', 'greenAt', 'seconds'].sort();
const lastLine = (res) => {
  const out = JSON.parse(res.stdout.trim().split(/\r?\n/).pop());
  assert.deepEqual(Object.keys(out).sort(), KEYS);
  return out;
};
const stateOf = (r) => JSON.parse(readFileSync(join(r.root, '.git', 'deliver', 'gate.json'), 'utf8'));
const { failedTests } = await import(pathToFileURL(SCRIPT).href);

test('given a test command that exits 0, when the gate runs, then the last line says green and the exit code is 0', () => {
  // Given
  const r = repo();

  // When
  const res = run(r, OK);

  // Then
  assert.equal(res.status, 0);
  assert.equal(lastLine(res).gate, 'green');
});

test('given a test command that exits 1, when the gate runs, then the last line says red and the exit code is 1', () => {
  // Given
  const r = repo();

  // When
  const res = run(r, FAIL);

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red');
});

test('given a command whose output stops growing, when a stuck check sees no growth, then it is killed and run once more, and a second stall is red: timeout', () => {
  // Given
  const r = repo();

  // When
  const res = run(r, STUCK, '--stuck-minutes', '0.03');

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red: timeout');
  assert.equal(logOf(r).split('start').length - 1, 2);
});

test('given a slow command whose output keeps growing, when the stuck check fires, then the gate keeps waiting and reports the real result', () => {
  // Given
  const r = repo();

  // When
  const res = run(r, SLOW, '--stuck-minutes', '0.03');

  // Then
  assert.equal(res.status, 0);
  assert.equal(lastLine(res).gate, 'green');
});

test('given a run longer than the wait cap, when the cap passes, then the gate answers running with exit 3 and a later --wait returns the result', () => {
  // Given
  const r = repo();

  // When
  const first = run(r, SLOW, '--stuck-minutes', '0', '--max-minutes', '0.01');
  const second = gate(r.root, '--wait');

  // Then
  assert.equal(first.status, 3);
  assert.equal(lastLine(first).gate, 'running');
  assert.equal(second.status, 0);
  assert.equal(lastLine(second).gate, 'green');
});

test('given a run in progress, when a second gate starts, then it exits 2 with a note to use --wait and the first run still ends green', () => {
  // Given
  const r = repo();
  const first = run(r, SLOW, '--stuck-minutes', '0', '--max-minutes', '0.01');

  // When
  const second = run(r, OK);
  const waited = gate(r.root, '--wait');

  // Then
  assert.equal(first.status, 3);
  assert.equal(second.status, 2);
  assert.match(second.stderr, /already running.*--wait/);
  assert.ok(!second.stdout.includes('green'));
  assert.equal(waited.status, 0);
  assert.equal(lastLine(waited).gate, 'green');
});

test('given a recorded run whose supervisor is gone, when the gate waits, then it reports red with "supervisor died" and exits 1', () => {
  // Given
  const r = repo();
  const dead = spawnSync(process.execPath, ['-e', '']).pid;
  mkdirSync(join(r.root, '.git', 'deliver'), { recursive: true });
  writeFileSync(join(r.root, '.git', 'deliver', 'gate.json'), JSON.stringify({
    run: { id: 'x', pid: dead, status: 'running', command: OK, stuckMinutes: 0, startedAt: Date.now(), opts: { root: r.root, head: r.head, tree: 't' } },
  }));

  // When
  const res = gate(r.root, '--wait');

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red');
  assert.equal(lastLine(res).test, 'supervisor died');
});

test('given a recorded supervisor pid that a different process now holds, when the gate waits, then it reports red with "supervisor died"', () => {
  // Given
  const r = repo();
  mkdirSync(join(r.root, '.git', 'deliver'), { recursive: true });
  writeFileSync(join(r.root, '.git', 'deliver', 'gate.json'), JSON.stringify({
    run: { id: 'x', pid: process.pid, pidStarted: Date.parse('2000-01-01T00:00:00Z'), status: 'running', command: OK, stuckMinutes: 0, startedAt: Date.now(), opts: { root: r.root, head: r.head, tree: 't' } },
  }));

  // When
  const res = gate(r.root, '--wait');

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).test, 'supervisor died');
});

test('given a --head that starts with a dash, when the gate runs with --no-scope, then it exits 2 and writes no file', () => {
  // Given
  const r = repo();
  const target = join(r.root, 'pwned.txt');

  // When
  const res = gate(r.root, '--head', `--output=${target}`, '--test', OK, '--no-scope');

  // Then
  assert.equal(res.status, 2);
  assert.equal(existsSync(target), false);
});

test('given no run recorded, when the gate runs with --wait, then it exits 2', () => {
  // Given
  const r = repo();

  // When
  const res = gate(r.root, '--wait');

  // Then
  assert.equal(res.status, 2);
  assert.ok(!res.stdout.includes('green'));
});

test('given a --max-minutes value that is not a number, when the gate runs, then it exits 2 and prints no green', () => {
  // Given
  const r = repo();

  // When
  const res = run(r, OK, '--max-minutes', 'soon');

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /max-minutes/);
  assert.ok(!res.stdout.includes('green'));
});

test('given no --test argument, when the gate runs, then it exits 2 and prints no green', () => {
  // Given
  const r = repo();

  // When
  const res = gate(r.root, '--head', r.head);

  // Then
  assert.equal(res.status, 2);
  assert.ok(!res.stdout.includes('green'));
});

test('given a green run and a file outside the perimeter, when the gate runs, then it reports red: scope and lists the file', () => {
  // Given
  const r = repo(['src/']);
  writeFileSync(join(r.root, 'other.txt'), 'x\n');

  // When
  const res = run(r, OK);

  // Then
  assert.equal(res.status, 1);
  const out = lastLine(res);
  assert.equal(out.gate, 'red: scope');
  assert.deepEqual(out.outside, ['other.txt']);
});

test('given a green gate, when it runs again on the same tree, then the tests are skipped and the last green is quoted', () => {
  // Given
  const r = repo();
  const first = lastLine(run(r, STAMP));
  const stamp = logOf(r);

  // When
  const res = run(r, STAMP);

  // Then
  assert.equal(res.status, 0);
  const out = lastLine(res);
  assert.equal(out.gate, 'skipped: tree unchanged');
  assert.equal(out.greenAt, first.greenAt);
  assert.equal(out.tree, first.tree);
  assert.equal(logOf(r), stamp);
});

test('given a green gate, when it runs again on the same tree with --force, then the tests run', () => {
  // Given
  const r = repo();
  run(r, STAMP);
  const stamp = logOf(r);

  // When
  const res = run(r, STAMP, '--force');

  // Then
  assert.equal(lastLine(res).gate, 'green');
  assert.notEqual(logOf(r), stamp);
});

test('given a green on a tree with a new file, when the perimeter narrows and the gate runs on the same tree, then it reports red: scope and does not skip', () => {
  // Given
  const r = repo();
  writeFileSync(join(r.root, 'other.txt'), 'x\n');
  const first = lastLine(run(r, OK));
  writeFileSync(join(r.root, '.git', 'deliver', 'perimeter.md'), `branch: ${git(r.root, 'rev-parse', '--abbrev-ref', 'HEAD')}\nstatus: active\n- src/\n`);

  // When
  const res = run(r, OK);

  // Then
  assert.equal(first.gate, 'green');
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red: scope');
  assert.deepEqual(lastLine(res).outside, ['other.txt']);
});

test('given a green gate, when a file changes and it runs again, then the tests run', () => {
  // Given
  const r = repo();
  run(r, STAMP);
  const stamp = logOf(r);
  writeFileSync(join(r.root, 'new.txt'), 'x\n');

  // When
  const res = run(r, STAMP);

  // Then
  assert.equal(lastLine(res).gate, 'green');
  assert.notEqual(logOf(r), stamp);
});

test('given a green stored for another test command or without the scope check, when the gate runs on the same tree, then the tests run', () => {
  // Given
  const r = repo();
  run(r, STAMP);
  const stamp = logOf(r);
  const other = 'node -e "console.log(Date.now()+0)"';

  // When
  const otherCommand = run(r, other);
  const afterOther = logOf(r);
  const noScope = run(r, other, '--no-scope');
  const afterNoScope = logOf(r);
  const scoped = run(r, other);

  // Then
  assert.equal(lastLine(otherCommand).gate, 'green');
  assert.notEqual(afterOther, stamp);
  assert.equal(lastLine(noScope).gate, 'green');
  assert.notEqual(afterNoScope, afterOther);
  assert.equal(lastLine(scoped).gate, 'green');
  assert.notEqual(logOf(r), afterNoScope);
});

test('given a file whose only change is whitespace, when the gate runs, then the file is listed as format-only', () => {
  // Given
  const r = repo();
  writeFileSync(join(r.root, 'README.md'), '  hello  \n');

  // When
  const res = run(r, OK);

  // Then
  assert.equal(lastLine(res).gate, 'green');
  assert.deepEqual(lastLine(res).formatOnly, ['README.md']);
});

test('given no active perimeter, when the gate runs, then it exits 2', () => {
  // Given
  const r = repo(null);

  // When
  const res = run(r, OK);

  // Then
  assert.equal(res.status, 2);
  assert.ok(!res.stdout.includes('green'));
});

const UNIT = 'node --test t.test.mjs';
const TEST_SOURCE = [
  "import { test } from 'node:test';",
  "import assert from 'node:assert/strict';",
  "import { existsSync } from 'node:fs';",
  "test('needs the flag file', () => assert.ok(existsSync(new URL('./flag.txt', import.meta.url))));",
  '',
].join('\n');

/** A repo holding one test file that passes only once `flag.txt` exists. */
function repoWithTest(flag = false) {
  const r = repo();
  writeFileSync(join(r.root, 't.test.mjs'), TEST_SOURCE);
  if (flag) writeFileSync(join(r.root, 'flag.txt'), 'x\n');
  return r;
}

const red = (r, unit = UNIT) => gate(r.root, '--red', '--unit', unit, '--test-files', 't.test.mjs');

test('given a unit command with one failing test, when the gate runs with --red, then it reports red-proven and exits 0', () => {
  // Given
  const r = repoWithTest();

  // When
  const res = red(r);

  // Then
  assert.equal(res.status, 0);
  assert.equal(lastLine(res).gate, 'red-proven');
  assert.match(lastLine(res).test, /needs the flag file/);
});

test('given a unit command that passes, when the gate runs with --red, then it reports red: no failing test', () => {
  // Given
  const r = repoWithTest(true);

  // When
  const res = red(r);

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red: no failing test');
});

test('given a proven red, when the tests pass with the test files unchanged, then the gate is green', () => {
  // Given
  const r = repoWithTest();
  red(r);
  writeFileSync(join(r.root, 'flag.txt'), 'x\n');

  // When
  const res = run(r, UNIT);

  // Then
  assert.equal(res.status, 0);
  assert.equal(lastLine(res).gate, 'green');
  assert.equal(stateOf(r).proof, undefined);
});

test('given a proven red, when a test file changed before the green run, then the gate reports red: tests changed', () => {
  // Given
  const r = repoWithTest();
  red(r);
  writeFileSync(join(r.root, 'flag.txt'), 'x\n');
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// weakened\n`);

  // When
  const res = run(r, UNIT);

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red: tests changed');
});

test('given a stored proof and a changed test file, when the gate runs with --force, then it drops the proof, says so and runs', () => {
  // Given
  const r = repoWithTest();
  red(r);
  writeFileSync(join(r.root, 'flag.txt'), 'x\n');
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited\n`);

  // When
  const res = run(r, UNIT, '--force');

  // Then
  const last = JSON.parse(res.stdout.trim().split(/\r?\n/).pop());
  assert.equal(res.status, 0);
  assert.equal(last.gate, 'green');
  assert.equal(last.proof, 'dropped');
  assert.equal(stateOf(r).proof, undefined);
});

test('given a stored proof and a changed test file, when the gate runs with --force and the tests fail, then the red line still says the proof was dropped', () => {
  // Given
  const r = repoWithTest();
  red(r);
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited\n`);

  // When
  const res = run(r, UNIT, '--force');

  // Then
  const last = JSON.parse(res.stdout.trim().split(/\r?\n/).pop());
  assert.equal(res.status, 1);
  assert.equal(last.gate, 'red');
  assert.equal(last.proof, 'dropped');
  assert.equal(stateOf(r).proof, undefined);
});

test('given a unit command with a failing test, when the gate proves it with --red, then gate.json holds the proof for the test file', () => {
  // Given
  const r = repoWithTest();

  // When
  red(r);

  // Then
  assert.deepEqual(Object.keys(stateOf(r).proof.files), ['t.test.mjs']);
});

test('given a green run, when the gate has started its command, then gate.json records the process as pid and start time', () => {
  // Given
  const r = repo();
  const before = Date.now();

  // When
  run(r, OK);

  // Then
  const procs = stateOf(r).procs;
  assert.equal(procs.length, 1);
  assert.ok(Number.isInteger(procs[0].pid) && procs[0].pid > 0);
  assert.ok(Date.parse(procs[0].started) >= before - 1000);
});

test('given a unit command whose only test file fails to load, when the gate runs with --red, then it reports red, not red-proven', () => {
  // Given
  const r = repo();
  writeFileSync(join(r.root, 't.test.mjs'), "import './missing.mjs';\n");

  // When
  const res = red(r);

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastLine(res).gate, 'red');
});

test('given dotnet output with a failed test, when the failures are read, then the test name is listed and the summary line is not', () => {
  // Given
  const log = '  Passed Calc.Subtracts [1 ms]\n  Failed Calc.Adds [12 ms]\n  Error Message: x\nFailed!  - Failed: 1, Passed: 1\n';

  // When
  const names = failedTests(log);

  // Then
  assert.deepEqual(names, ['Calc.Adds']);
});

test('given node spec output, when the failures are read, then each failed test is listed once and "failing tests:" is not', () => {
  // Given
  const log = '✔ fine (1.2ms)\n✖ adds (2.5ms)\nℹ fail 1\n✖ failing tests:\n\n✖ adds (2.5ms)\n';

  // When
  const names = failedTests(log);

  // Then
  assert.deepEqual(names, ['adds']);
});

test('given node TAP output where a file failed to load, when the failures are read, then the file is no test and a real failure stays', () => {
  // Given
  const log = 'TAP version 13\nnot ok 1 - C:\\repo\\t.test.mjs\nnot ok 2 - src/other.mjs\nnot ok 3 - adds\n';

  // When
  const withFiles = failedTests(log, ['src/other.mjs']);
  const loadOnly = failedTests('not ok 1 - C:\\repo\\t.test.mjs\n');

  // Then
  assert.deepEqual(withFiles, ['adds']);
  assert.deepEqual(loadOnly, []);
});

test('given vitest output, when the failures are read, then the FAIL and × lines name the test and a file-level FAIL is no test', () => {
  // Given
  const log = ' ❯ src/a.test.ts (1 test | 1 failed)\n   × adds 3ms\n FAIL  src/a.test.ts > adds\nAssertionError\n FAIL  src/b.test.ts [ src/b.test.ts ]\n';

  // When
  const names = failedTests(log);

  // Then
  assert.deepEqual(names, ['adds']);
});

test('given jest output, when the failures are read, then only a "suite › test" line counts, not Console or "Test suite failed to run"', () => {
  // Given
  const log = ' FAIL src/a.test.js\n  ● Console\n\n  ● Math › adds\n\n  ● Test suite failed to run\n';

  // When
  const names = failedTests(log);
  const suiteOnly = failedTests(' FAIL src/b.test.js\n  ● Test suite failed to run\n');

  // Then
  assert.deepEqual(names, ['Math › adds']);
  assert.deepEqual(suiteOnly, []);
});

test("given a runner the gate can't read, when it runs with --red, then it exits 2", () => {
  // Given
  const r = repoWithTest();

  // When
  const res = red(r, FAIL);

  // Then
  assert.equal(res.status, 2);
  assert.ok(!res.stdout.includes('red-proven'));
});
